-- KA Beauty OS — seed V25, parte: Estúdio, equipe, catálogo, modelos de anamnese e clientes. Encoding: UTF-8
-- Incluído por supabase/seed/02_v25_dados_teste.sql (não rodar sozinho).

-- ─── 2. Estúdio, equipe, catálogo e modelos ──────────────────
update public.organizations
   set city = 'Benalmádena', timezone = 'Europe/Madrid', currency = 'EUR', locale = 'pt-BR'
 where id = current_setting('seed.org_id')::uuid;

insert into public.staff_members (id, org_id, name, email, phone, color, role, bio, commission_pct, online_booking, visible, active, position)
select pg_temp.sid(s.chave), current_setting('seed.org_id')::uuid, s.nome, s.email, s.tel, s.cor, s.funcao, s.bio, s.pct, true, true, true, s.pos
from (values
  ('prof-karenn', 'Karenn Guimarães', 'karenn@exemplo.es', '+34600000091', '#4F6A8F', 'Proprietária', 'Micropigmentação, lábios e sobrancelhas', 0, 0),
  ('prof-bruna', 'Bruna Reis', 'bruna.reis@exemplo.es', '+34600000092', '#5C7F6A', 'Esteticista · Facial', 'Limpeza de pele, peeling e hidratação', 40, 1)
) s(chave, nome, email, tel, cor, funcao, bio, pct, pos)
on conflict (id) do update set name = excluded.name, email = excluded.email, phone = excluded.phone, color = excluded.color,
  role = excluded.role, bio = excluded.bio, commission_pct = excluded.commission_pct, active = true, visible = true;

-- Tipos de bloqueio padrão (o gatilho do estúdio já cria; aqui só garante os dois usados).
insert into public.time_block_types (org_id, name, color, is_paid)
values (current_setting('seed.org_id')::uuid, 'Almoço', '#F59E0B', false),
       (current_setting('seed.org_id')::uuid, 'Formação', '#16A34A', true)
on conflict (org_id, name) do nothing;

-- Turnos: Karenn seg–sáb 09–19; Bruna seg–sex 09–19 e sáb 09–14. Domingo fechado.
insert into public.staff_shifts (id, org_id, staff_id, day_of_week, start_time, end_time, active)
select pg_temp.sid(p.chave || '-turno-' || d), current_setting('seed.org_id')::uuid, pg_temp.sid(p.chave), d,
       '09:00', case when p.chave = 'prof-bruna' and d = 6 then '14:00' else '19:00' end, true
from (values ('prof-karenn'), ('prof-bruna')) p(chave), generate_series(1, 6) d
on conflict (staff_id, day_of_week) do update set start_time = excluded.start_time, end_time = excluded.end_time, active = true;

insert into public.service_categories (id, org_id, name, color, position, active)
select pg_temp.sid('categoria-' || c.chave), current_setting('seed.org_id')::uuid, c.nome, c.cor, c.pos, true
from (values ('micro', 'Micropigmentação', '#4F6A8F', 0), ('labios', 'Lábios', '#B0583A', 1),
             ('sobrancelhas', 'Sobrancelhas', '#A07A2C', 2), ('facial', 'Facial', '#5C7F6A', 3)) c(chave, nome, cor, pos)
on conflict (id) do update set name = excluded.name, color = excluded.color, position = excluded.position, active = true;

-- Modelos de anamnese do sistema (src/data/anamnese/system-templates.ts), congelados aqui
-- (perguntas em JSON; termo como texto JSON numa linha só).
create temp table seed_modelo_base (chave text primary key, questions jsonb not null, consent text not null);
insert into seed_modelo_base values
  ('micro-es', $j$[{"id":"s_path","text":"Patología y otros","type":"section","required":false},{"id":"i_note","text":"La información marcada con asteriscos impide que el cliente se someta al procedimiento sin autorización médica, y el glaucoma impide el procedimiento en los párpados.","type":"info","required":false},{"id":"allergy","text":"Alergia","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"depression","text":"Depresión","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"epilepsy","text":"Epilepsia","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"herpes","text":"Herpes Labial","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"hypertension","text":"Hipertensión","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"smoker","text":"Tabaquismo","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"cardiovascular","text":"Enfermedad Cardiovascular","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"circulatory","text":"Enfermedad Circulatoria","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"renal","text":"Enfermedad Renal","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"respiratory","text":"Enfermedad Respiratoria","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"menstrual","text":"Período Menstrual","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"keloid","text":"Queloide","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"tattoo","text":"Tatuaje","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"botox","text":"Aplicación reciente de Botox","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"cancer","text":"* Cáncer","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"hiv","text":"* VIH +","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"pacemaker","text":"* Marcapasos","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"breastfeeding","text":"* Lactancia materna","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"diabetes","text":"* Diabetes","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"glaucoma","text":"* Glaucoma","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"hepatitis","text":"* Hepatitis","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"pregnant","text":"* Embarazada","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"medication","text":"¿Toma algún medicamento?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cuál(es)?"},{"id":"old_procedure","text":"¿Tiene procedimiento antiguo?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cuál? ¿A cuánto tiempo?"},{"id":"s_cosmetic","text":"Información cosmética","type":"section","required":false},{"id":"cosmetic_recent","text":"¿Se ha realizado recientemente algún procedimiento cosmético en la cara?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cuál(es)?"},{"id":"cosmetic_use","text":"¿Utiliza algún cosmético o medicamento en la cara?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cuál(es)?"},{"id":"peeling","text":"¿Tiene algún tipo de descamación o cicatriz en la zona que será micropigmentada?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"Detalle:"}]$j$, $j$"TÉRMINO DE AUTORIZACIÓN PARA MICROPIGMENTACIÓN\nAutorizo a la profesional KARENN GUIMARÃES a realizar en mi piel el procedimiento de Micropigmentación. Declaro que:\n1. Comprendo que la micropigmentación es un procedimiento cosmético para realzar características faciales, con resultados duraderos, pero que pueden exigir retoques y mantenimientos anuales. La durabilidad puede variar de 6 meses a 2 años, según la técnica, cuidados y tipo de piel.\n2. He sido informada sobre el objetivo, descripción, resultados esperados, riesgos, complicaciones, contraindicaciones y tratamientos alternativos, y he tenido la oportunidad de aclarar todas mis dudas.\n3. Estoy consciente de los riesgos (enrojecimiento, hinchazón, alteraciones en el color del pigmento, reacciones alérgicas, infección, cicatrices y asimetrías). No me encuadro en la lista de clientes de riesgo, no presento enfermedad infectocontagiosa, ni síntomas de debilidad inmunológica, ni soy dependiente de alcohol o drogas.\n4. Acepto seguir todas las instrucciones de cuidados post-tratamiento (pomadas, evitar exposición solar y productos químicos agresivos). Asumo total responsabilidad por el post-procedimiento.\n5. La profesional me instruyó sobre el procedimiento, diseño adecuado para la forma de mi rostro, el color de pigmento y las condiciones de retoque.\n6. Renuncio por voluntad propia a la prueba de sensibilidad y asumo total responsabilidad por cualquier reacción de mi piel.\n7. Autorizo a la profesional a fotografiar y filmar el antes/después para documentación, book, fines científicos, de marketing y redes sociales, sin ningún reembolso.\n8. La segunda sesión de retoque, si fuera necesaria, deberá realizarse entre 30 y 60 días después de la primera, con coste adicional. Después de 60 días se considera mantenimiento con un nuevo valor.\n9. Estoy consciente de que mantenimientos anuales pueden ser necesarios y de que después de 1 año el procedimiento tendrá el valor de uno nuevo. Declaro que la información anterior es verdadera y acepto voluntariamente someterme al tratamiento de micropigmentación.\n\nTÉRMINO DE AUTORIZACIÓN DE USO DE IMAGEN\nAutorizo a la profesional a fotografiar y filmar el antes y después del/los procedimiento(s) realizado(s) en mí, para fines de divulgación en su portafolio, redes sociales como Instagram y Facebook, materiales promocionales, catálogos y similares, sin recibir ningún reembolso o pago por el uso de mis imágenes. Declaro que:\n- Comprendo que la divulgación de mis imágenes tiene como objetivo mostrar los resultados del trabajo de la profesional e inspirar a otras personas a conocer los beneficios del procedimiento.\n- Las imágenes serán tratadas con profesionalismo y respeto, y mi rostro podrá ser desenfocado u ocultado en caso de que yo lo prefiera.\n- La información personal contenida en las imágenes se mantendrá en secreto y no se divulgará sin mi autorización expresa.\n- La autorización se concede a título gratuito e irrevocable.\nDeclaro que he leído y comprendido toda la información anterior y acepto voluntariamente el uso de mi imagen."$j$::jsonb #>> '{}'),
  ('micro-en', $j$[{"id":"s_path","text":"Pathology and others","type":"section","required":false},{"id":"i_note","text":"Items marked with * prevent the client from undergoing the procedure without the doctor's authorization, and glaucoma prevents the procedure in the eyes.","type":"info","required":false},{"id":"allergy","text":"Allergy","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"depression","text":"Depression","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"epilepsy","text":"Epilepsy","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"herpes","text":"Oral Herpes","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"hypertension","text":"Hypertension","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"smoker","text":"Smoker","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"cardiovascular","text":"Cardiovascular Disease","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"circulatory","text":"Circulatory Disease","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"renal","text":"Renal Disease","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"respiratory","text":"Respiratory Disease","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"menstrual","text":"Menstrual Period","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"keloid","text":"Keloid","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"tattoo","text":"Tattoo","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"botox","text":"Recent Botox Application","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"cancer","text":"* Cancer","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"hiv","text":"* HIV +","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"pacemaker","text":"* Pacemaker","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"breastfeeding","text":"* Breastfeeding","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"diabetes","text":"* Diabetes","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"glaucoma","text":"* Glaucoma","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"hepatitis","text":"* Hepatitis","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"pregnant","text":"* Pregnant","type":"yes_no","required":true,"options":["YES","NO"]},{"id":"medication","text":"Do you take any medication?","type":"yes_no","required":true,"options":["YES","NO"],"explainWhenAnswer":"YES","explanationLabel":"Which?"},{"id":"old_procedure","text":"Do you have an old procedure?","type":"yes_no","required":true,"options":["YES","NO"],"explainWhenAnswer":"YES","explanationLabel":"Which? How long ago?"},{"id":"s_cosmetic","text":"Cosmetic information","type":"section","required":false},{"id":"cosmetic_recent","text":"Have you recently had any cosmetic procedures on your face?","type":"yes_no","required":true,"options":["YES","NO"],"explainWhenAnswer":"YES","explanationLabel":"Which?"},{"id":"cosmetic_use","text":"Do you use any cosmetics or medicine on your face?","type":"yes_no","required":true,"options":["YES","NO"],"explainWhenAnswer":"YES","explanationLabel":"Which?"},{"id":"peeling","text":"Do you have any type of peeling or scarring in the area to be micropigmented?","type":"yes_no","required":true,"options":["YES","NO"],"explainWhenAnswer":"YES","explanationLabel":"Describe:"}]$j$, $j$"MICROPIGMENTATION AUTHORIZATION FORM\nI hereby authorize the professional KARENN GUIMARÃES to perform the Micropigmentation procedure on my skin. I declare that:\n1. I understand that micropigmentation is a cosmetic procedure to enhance facial features, with long-lasting results that may require annual touch-ups and maintenance. The durability can vary from 6 months to 2 years, depending on the technique, care, and skin type.\n2. I have been informed about the purpose, description, expected results, risks, complications, contraindications, and alternative treatments, and I have had the opportunity to clarify all my doubts.\n3. I am aware of the risks (redness, swelling, changes in pigment color, allergic reactions, infection, scarring, and asymmetries). I do not fall into the list of at-risk clients, I have no infectious contagious diseases, no symptoms of immune deficiency, nor am I dependent on alcohol or drugs.\n4. I agree to follow all post-treatment care instructions (ointments, avoiding sun exposure and aggressive chemicals). I assume full responsibility for the post-procedure.\n5. The professional has instructed me regarding the procedure, appropriate design for my face shape, pigment color, and touch-up conditions.\n6. I voluntarily waive the sensitivity test application and assume full responsibility for any skin reaction.\n7. I authorize the professional to photograph and film the before/after for documentation, portfolio, scientific, marketing, and social media purposes, without any reimbursement.\n8. The second touch-up session, if necessary, should be performed between 30 and 60 days after the first session, with an additional cost. After 60 days it is considered maintenance with a new price.\n9. I am aware that annual maintenance may be necessary and that after 1 year the procedure will have the value of a new procedure. I declare the above information is true and voluntarily agree to undergo the micropigmentation treatment.\n\nIMAGE USAGE AUTHORIZATION FORM\nI authorize the professional to photograph and film the before and after of the procedure(s) performed on me, for the purpose of promotion in her portfolio, social media such as Instagram and Facebook, promotional materials, catalogs, and similar, without receiving any reimbursement or payment for the use of my images. I declare that:\n- I understand that the disclosure of my images is intended to show the results of the professional's work and inspire other people to learn about the benefits of the procedure.\n- The images will be treated with professionalism and respect, and my face may be blurred or hidden if I prefer.\n- The personal information contained in the images will be kept confidential and will not be disclosed without my express authorization.\n- The authorization is granted free of charge and is irrevocable.\nI declare that I have read and understood all the above information and voluntarily agree to the use of my image."$j$::jsonb #>> '{}'),
  ('laser-es', $j$[{"id":"s_path","text":"Patología y otros","type":"section","required":false},{"id":"i_note","text":"La información marcada con asteriscos impide que el cliente se someta al procedimiento sin autorización médica.","type":"info","required":false},{"id":"allergy","text":"Alergia","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"depression","text":"Depresión","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"epilepsy","text":"Epilepsia","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"herpes","text":"Herpes Labial","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"hypertension","text":"Hipertensión","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"smoker","text":"Tabaquismo","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"acid","text":"¿Utilizas algún ácido?","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"circulatory","text":"Enfermedad Circulatoria","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"renal","text":"Enfermedad Renal","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"botox","text":"Aplicación reciente de Botox","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"menstrual","text":"Período Menstrual","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"keloid","text":"Queloide","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"tattoo","text":"Tatuaje","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"blood_donor","text":"* Donante de sangre","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"cancer","text":"* Cáncer","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"hiv","text":"* VIH +","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"pacemaker","text":"* Marcapasos","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"breastfeeding","text":"* Lactancia materna","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"diabetes","text":"* Diabetes","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"isotretinoin","text":"* Isotretinoína (Roacutan)","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"hepatitis","text":"* Hepatitis","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"pregnant","text":"* Embarazada","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"medication","text":"¿Toma algún medicamento?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cuál(es)?"},{"id":"tattoo_age","text":"¿Cuál es la edad de tu micro/tatuaje?","type":"text","required":true},{"id":"s_history","text":"Historial de remoción","type":"section","required":false},{"id":"prior_removal","text":"¿Alguna vez has intentado eliminar tu tatuaje/micro antes?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cómo?"},{"id":"pre_info","text":"Describe cualquier información que considere necesario comunicar al profesional antes del procedimiento:","type":"text","required":false},{"id":"s_info","text":"Información importante","type":"section","required":false},{"id":"i_info","text":"1. Ácido: suspender su uso al menos 15 días antes del procedimiento. 2. Isotretinoína (Roacutan): esperar al menos 3 meses tras finalizar el tratamiento. 3. Diabetes: la curación es más lenta y la piel puede volverse más roja inmediatamente después de la sesión. 4. Donante de sangre: donar antes del procedimiento o después de 1 año.","type":"info","required":false}]$j$, $j$"AUTORIZACIÓN PARA REMOCIÓN LÁSER\nDeclaro, para todos los fines legales, que la información proporcionada es veraz y confirmo mi deseo de realizar el procedimiento de remoción láser con la profesional KARENN GUIMARÃES.\n1. He sido debidamente informado sobre el procedimiento y los riesgos asociados, tales como: hinchazón y/o reacción alérgica por estimulación del pigmento; formación de costras durante la cicatrización (no deben removerse prematuramente); riesgos de quemaduras, especialmente en pieles sensibles; posibles alteraciones en el color del pigmento; retraso o resistencia al láser en caso de remoción previa por otros métodos; posible decoloración blanca del pelo en el área tratada; hiperpigmentación o hipopigmentación; riesgo de formación de cicatrices, incluyendo queloides, en personas predispuestas. Soy consciente de todas las condiciones y de mi estado general de salud, eximiendo a la profesional y al establecimiento de responsabilidad por reacciones adversas, siempre que el procedimiento se realice según las buenas prácticas.\n2. En caso de paquete de sesiones, no habrá reembolso íntegro en caso de desistimiento: solo se reembolsará el 85% de las sesiones no realizadas, y las sesiones ya realizadas se calculan según el precio unitario, no el del paquete.\n3. No me encuadro en la lista de clientes de riesgo, no poseo enfermedad infectocontagiosa, ni síntomas de debilidad inmunológica, ni soy dependiente de alcohol o drogas.\n4. Asumo total responsabilidad por los cuidados post-remoción láser, siguiendo rigurosamente las instrucciones de la profesional.\n5. Al iniciar el procedimiento, la profesional informará y presentará los productos que se utilizarán.\n6. Todo el material utilizado es desechable y el ambiente de trabajo sigue rigurosos protocolos de higiene y esterilización.\n7. Autorizo, a título gratuito, fotografías y/o videos del procedimiento y su utilización para divulgar el trabajo de la profesional en cualquier medio.\nDeclaro haber leído atentamente este término, comprendo íntegramente su contenido y estoy de acuerdo con todos sus términos y condiciones.\n\nTÉRMINO DE AUTORIZACIÓN DE USO DE IMAGEN\nAutorizo a la profesional a fotografiar y filmar el antes y después del/los procedimiento(s) realizado(s) en mí, para fines de divulgación en su portafolio, redes sociales como Instagram y Facebook, materiales promocionales, catálogos y similares, sin recibir ningún reembolso o pago por el uso de mis imágenes. Declaro que:\n- Comprendo que la divulgación de mis imágenes tiene como objetivo mostrar los resultados del trabajo de la profesional e inspirar a otras personas a conocer los beneficios del procedimiento.\n- Las imágenes serán tratadas con profesionalismo y respeto, y mi rostro podrá ser desenfocado u ocultado en caso de que yo lo prefiera.\n- La información personal contenida en las imágenes se mantendrá en secreto y no se divulgará sin mi autorización expresa.\n- La autorización se concede a título gratuito e irrevocable.\nDeclaro que he leído y comprendido toda la información anterior y acepto voluntariamente el uso de mi imagen."$j$::jsonb #>> '{}'),
  ('facial-es', $j$[{"id":"s_salud","text":"Salud de la piel","type":"section","required":false},{"id":"allergy","text":"Alergias (cosméticos, látex, medicamentos)","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cuál(es)?"},{"id":"pregnant","text":"Embarazo o lactancia","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"isotretinoin","text":"Isotretinoína (Roacutan) en los últimos 6 meses","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"acid","text":"¿Utiliza ácidos o retinol en la piel?","type":"yes_no","required":true,"options":["SÍ","NO"],"explainWhenAnswer":"SÍ","explanationLabel":"¿Cuál(es)?"},{"id":"sun","text":"¿Se expuso al sol en los últimos 7 días?","type":"yes_no","required":true,"options":["SÍ","NO"]},{"id":"skin_type","text":"¿Cómo describe su piel?","type":"text","required":false}]$j$,
   $j$TÉRMINO DE CONSENTIMIENTO PARA TRATAMIENTO FACIAL
Declaro que la información anterior es verdadera, que fui informada sobre el procedimiento, sus cuidados y posibles reacciones (enrojecimiento, sensibilidad, descamación leve) y acepto voluntariamente realizar el tratamiento.$j$);

insert into public.anamnese_templates (id, org_id, title, description, questions, consent_text, consent_version, professional_form, active, is_active, updated_at)
select pg_temp.sid('modelo-' || m.chave), current_setting('seed.org_id')::uuid, m.titulo, m.descricao, b.questions, b.consent,
       m.versao, m.ficha::jsonb, true, m.publicado, now() - make_interval(days => m.idade)
from (values
  ('cejas', 'Micropigmentación de cejas', 'Shadow, Microblading, Brows Repair e Retoque anual', 'micro-es', 'v3', '{"type":"micropigmentation"}', true, 230),
  ('cejas-en', 'Eyebrow micropigmentation', 'Shadow e Microblading, para clientes em inglês', 'micro-en', 'v1', '{"type":"micropigmentation"}', true, 238),
  ('labios', 'Micropigmentación labial', 'Aquarele Lips e Lip Blush', 'micro-es', 'v2', '{"type":"micropigmentation"}', true, 269),
  ('facial', 'Facial', 'Peeling suave e Dermaplaning', 'facial-es', 'v1', '{"type":"facial"}', true, 282),
  ('laser', 'Remoción láser', 'Rascunho: nenhum serviço vinculado', 'laser-es', 'v1', '{"type":"laser_removal"}', false, 5)
) m(chave, titulo, descricao, base, versao, ficha, publicado, idade)
join seed_modelo_base b on b.chave = m.base
on conflict (id) do update set title = excluded.title, description = excluded.description, questions = excluded.questions,
  consent_text = excluded.consent_text, consent_version = excluded.consent_version,
  professional_form = excluded.professional_form, active = true, is_active = excluded.is_active;

-- Durabilidade, retoque incluído e sinal por serviço não têm coluna no banco; a duração
-- mínima é 15 min (CHECK), então Aquarele Lips e Lip Blush ficam com 2 h e fora da reserva online.
insert into public.services (id, org_id, category_id, name, description, price, price_type, duration_minutes,
  requires_anamnese, anamnese_template_id, online_booking, commission_pct, position, active)
select pg_temp.sid('servico-' || s.chave), current_setting('seed.org_id')::uuid, pg_temp.sid('categoria-' || s.cat), s.nome, s.descr,
       s.preco, 'fixed', s.dur, s.modelo is not null, case when s.modelo is null then null else pg_temp.sid('modelo-' || s.modelo) end,
       s.online, case when s.cat = 'facial' then 40 else 0 end, s.pos, true
from (values
  ('shadow', 'micro', 'Shadow', 'Sombreado suave para um efeito pó de sobrancelha. Inclui anestesia tópica.', 230, 150, 'cejas', true, 0),
  ('microblading', 'micro', 'Microblading', 'Fios finos desenhados fio a fio, resultado natural.', 230, 150, 'cejas', true, 1),
  ('brows_repair', 'micro', 'Brows Repair', 'Correção e reforço de trabalho anterior. Existe pacote de 3 sessões.', 50, 90, 'cejas', true, 2),
  ('retoque_anual', 'micro', 'Retoque anual', 'Atualização do pigmento após 12 meses.', 90, 90, 'cejas', true, 3),
  ('aquarele', 'labios', 'Aquarele Lips', 'Efeito aquarela com cor translúcida e contorno suave.', 250, 120, 'labios', false, 0),
  ('lip_blush', 'labios', 'Lip Blush', 'Cor natural e uniforme para realçar os lábios.', 250, 120, 'labios', false, 1),
  ('hydragloss', 'labios', 'Hydragloss labial', 'Hidratação profunda e brilho imediato.', 40, 45, null, true, 2),
  ('diseno_lujo', 'sobrancelhas', 'Diseño de cejas · Lujo', 'Desenho personalizado com henna ou tintura.', 40, 50, null, true, 0),
  ('diseno_basico', 'sobrancelhas', 'Diseño de cejas · Básico', 'Desenho com pinça e cera.', 20, 30, null, true, 1),
  ('laminado', 'sobrancelhas', 'Laminado de cejas', 'Fios alinhados e fixados para mais volume.', 45, 60, null, true, 2),
  ('henna', 'sobrancelhas', 'Henna de cejas', 'Coloração com henna que também tinge a pele.', 30, 40, null, true, 3),
  ('depilacao', 'sobrancelhas', 'Depilação de cejas', 'Limpeza e acabamento do desenho.', 12, 20, null, true, 4),
  ('limpieza_profunda', 'facial', 'Limpieza facial profunda', 'Higienização, extração e máscara calmante.', 60, 75, null, true, 0),
  ('peeling', 'facial', 'Peeling suave', 'Renovação superficial para pele opaca.', 55, 60, 'facial', true, 1),
  ('hidratacao', 'facial', 'Hidratação facial', 'Máscara nutritiva e massagem relaxante.', 48, 55, null, true, 2),
  ('limpieza_express', 'facial', 'Limpieza facial express', 'Versão rápida para manutenção entre sessões.', 35, 40, null, true, 3),
  ('dermaplaning', 'facial', 'Dermaplaning', 'Esfoliação mecânica com lâmina, pele lisa na hora.', 65, 50, 'facial', true, 4)
) s(chave, cat, nome, descr, preco, dur, modelo, online, pos)
on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, description = excluded.description,
  price = excluded.price, duration_minutes = excluded.duration_minutes, requires_anamnese = excluded.requires_anamnese,
  anamnese_template_id = excluded.anamnese_template_id, online_booking = excluded.online_booking,
  commission_pct = excluded.commission_pct, position = excluded.position, active = true;

-- Karenn faz tudo; Bruna faz a categoria Facial.
delete from public.service_staff where org_id = current_setting('seed.org_id')::uuid
  and staff_id in (pg_temp.sid('prof-karenn'), pg_temp.sid('prof-bruna'));
insert into public.service_staff (service_id, staff_id, org_id)
select s.id, p.id, s.org_id from public.services s
join public.staff_members p on p.org_id = s.org_id
  and (p.id = pg_temp.sid('prof-karenn') or (p.id = pg_temp.sid('prof-bruna') and s.category_id = pg_temp.sid('categoria-facial')))
where s.org_id = current_setting('seed.org_id')::uuid and s.id = any(array(select pg_temp.sid('servico-' || k) from unnest(array[
  'shadow','microblading','brows_repair','retoque_anual','aquarele','lip_blush','hydragloss','diseno_lujo','diseno_basico',
  'laminado','henna','depilacao','limpieza_profunda','peeling','hidratacao','limpieza_express','dermaplaning']) k));

insert into public.service_packages (id, org_id, name, description, price, sessions, validity_days, online_booking, active, position)
values (pg_temp.sid('pacote-brows-repair'), current_setting('seed.org_id')::uuid, 'Brows Repair · 3 sessões',
        'Correção gradual de um trabalho anterior', 130, 3, 180, false, true, 0)
on conflict (id) do update set name = excluded.name, description = excluded.description, price = excluded.price,
  sessions = excluded.sessions, validity_days = excluded.validity_days, active = true;
delete from public.package_services where package_id = pg_temp.sid('pacote-brows-repair');
insert into public.package_services (package_id, service_id, qty, org_id)
values (pg_temp.sid('pacote-brows-repair'), pg_temp.sid('servico-brows_repair'), 1, current_setting('seed.org_id')::uuid);

