insert into public.clients (id, org_id, full_name, phone, phone_country_code, email, birth_date, tags, alert_type, alert_text,
  source, status, created_at)
select pg_temp.cliente(c.n), current_setting('seed.org_id')::uuid, c.nome, '+346000000' || lpad(c.n::text, 2, '0'), '+34',
       c.email || '@exemplo.es',
       case when c.aniversario is not null
         then make_date(1986 + c.n % 12, extract(month from pg_temp.dia(0))::int, c.aniversario)
         else make_date(1975 + c.n % 25, (extract(month from pg_temp.dia(0))::int + c.n % 11) % 12 + 1, 1 + (c.n * 7) % 28) end,
